import java.util.*;

class Solution {
  private static final long MOD = 1_000_000_007L;

  public int countAnagrams(String s) {
    String[] words = s.split(" ");
    int length = 0;
    for (String word : words) length = Math.max(length, word.length());
    long[] factorial = new long[s.length() + 1];
    long[] inverse = new long[s.length() + 1];
    factorial[0] = 1;
    for (int i = 1; i <= s.length(); i++) factorial[i] = factorial[i - 1] * i % MOD;
    inverse[s.length()] = power(factorial[s.length()], MOD - 2);
    for (int i = s.length(); i > 0; i--) inverse[i - 1] = inverse[i] * i % MOD;
    long answer = 1;
    for (String word : words) {
      int[] count = new int[26];
      for (int i = 0; i < word.length(); i++) count[word.charAt(i) - 'a']++;
      long ways = factorial[word.length()];
      for (int value : count) ways = ways * inverse[value] % MOD;
      answer = answer * ways % MOD;
    }
    return (int) answer;
  }

  private long power(long base, long exponent) {
    long result = 1;
    while (exponent > 0) {
      if ((exponent & 1) != 0) result = result * base % MOD;
      base = base * base % MOD;
      exponent >>= 1;
    }
    return result;
  }
}
